// Akıllı çöp kutusu: el yaklaşınca servo kapağı açar, bir süre sonra kapatır.
#include <Servo.h>  // Arduino IDE ile gelir

const int TRIG_PIN = 12;
const int ECHO_PIN = 11;
const int SERVO_PIN = 9;

const int ESIK_CM = 15;                       // bundan yakın el kapağı açar
const int KAPALI_ACI = 0;                     // kapak kapalıyken servo açısı
const int ACIK_ACI = 100;                     // kapak açıkken servo açısı
const unsigned long ACIK_KALMA_MS = 3000;     // el gidince kapak bu kadar açık kalır

Servo kapak;
bool acik = false;
unsigned long sonGorulme = 0;  // elin en son görüldüğü an

// Mesafeyi cm olarak döndürür; yankı gelmezse 0.
long mesafeOlc() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);
  long sure = pulseIn(ECHO_PIN, HIGH, 30000);  // en çok 30 ms bekle (~5 m)
  return sure / 58;
}

void setup() {
  Serial.begin(9600);
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  kapak.attach(SERVO_PIN);
  kapak.write(KAPALI_ACI);
  Serial.println("Hazir. Elini yaklastir.");
}

void loop() {
  long cm = mesafeOlc();

  if (cm > 0 && cm < ESIK_CM) {
    sonGorulme = millis();
    if (!acik) {
      kapak.write(ACIK_ACI);
      acik = true;
      Serial.print("El algilandi (");
      Serial.print(cm);
      Serial.println(" cm): kapak acildi.");
    }
  }

  if (acik && millis() - sonGorulme > ACIK_KALMA_MS) {
    kapak.write(KAPALI_ACI);
    acik = false;
    Serial.println("Kapak kapandi.");
  }
  delay(100);
}
